INSERT INTO policies (policy_id, policy_number, title, category, owner_faculty_id, effective_from, effective_to, version, status, source_type, source_document, record) VALUES ('POLICY-001', 'CM-SYN-POL-001', 'Attendance Policy (Demo)', 'attendance', 'FAC-IT-001', '2026-07-01', '2027-06-30', '1.0', 'active', 'synthetic', 'DOC-POLICIES-001', '{"source_type": "synthetic", "source_document": "DOC-POLICIES-001", "academic_year": "2026-2027", "policy_id": "POLICY-001", "policy_number": "CM-SYN-POL-001", "title": "Attendance Policy (Demo)", "category": "attendance", "applies_to_department_ids": ["DEPT-IT-001"], "applies_to_program_ids": ["PROG-BTECH-IT-001", "PROG-MTECH-IT-001"], "related_course_ids": [], "related_lab_ids": [], "related_facility_ids": [], "owner_faculty_id": "FAC-IT-001", "summary": "Sets the demo minimum attendance expectation for IT courses.", "clauses": ["Students are expected to attend at least 75% of lecture and 80% of laboratory sessions in each course (synthetic threshold).", "Attendance is reviewed at mid-semester (see calendar CAL-2026-27-006) and before the end-semester examinations.", "Students below threshold receive a written advisory from the course faculty and may be asked to meet the Head of Department (FAC-IT-001).", "Medical or institutional-duty absences must be reported to the Department Office (FCL-IT-010) within 7 days."], "synthetic_notice": "This is a synthetic policy created for CampusMate testing. It is not a Ganpat University regulation.", "effective_from": "2026-07-01", "effective_to": "2027-06-30", "version": "1.0", "status": "active"}');
