INSERT INTO policies (policy_id, policy_number, title, category, owner_faculty_id, effective_from, effective_to, version, status, source_type, source_document, record) VALUES ('POLICY-002', 'CM-SYN-POL-002', 'Laboratory Usage Policy (Demo)', 'laboratory', 'FAC-IT-001', '2026-07-01', '2027-06-30', '1.0', 'active', 'synthetic', 'DOC-POLICIES-001', '{"source_type": "synthetic", "source_document": "DOC-POLICIES-001", "academic_year": "2026-2027", "policy_id": "POLICY-002", "policy_number": "CM-SYN-POL-002", "title": "Laboratory Usage Policy (Demo)", "category": "laboratory", "applies_to_department_ids": ["DEPT-IT-001"], "applies_to_program_ids": ["PROG-BTECH-IT-001", "PROG-MTECH-IT-001"], "related_course_ids": [], "related_lab_ids": ["LAB-IT-001", "LAB-IT-002", "LAB-IT-003", "LAB-IT-004", "LAB-IT-005", "LAB-IT-006", "LAB-IT-007", "LAB-IT-008", "LAB-IT-009", "LAB-IT-010"], "related_facility_ids": [], "owner_faculty_id": "FAC-IT-001", "summary": "Rules for using any of the ten IT department laboratories LAB-IT-001 to LAB-IT-010.", "clauses": ["Students may use a laboratory only during scheduled practicals or after registering a lab slot with the responsible faculty member of that lab.", "Lab slot registration opens every Monday at 09:00 through the department office email it-labs@campusmate-demo.example.", "Personal software may not be installed on lab workstations; requests go to the lab''s responsible faculty.", "Lab computers must be logged off and seats left clean at the end of each session.", "Repeated violations are reported to the Head of Department."], "synthetic_notice": "This is a synthetic policy created for CampusMate testing. It is not a Ganpat University regulation.", "effective_from": "2026-07-01", "effective_to": "2027-06-30", "version": "1.0", "status": "active"}');
