INSERT INTO policies (policy_id, policy_number, title, category, owner_faculty_id, effective_from, effective_to, version, status, source_type, source_document, record) VALUES ('POLICY-003', 'CM-SYN-POL-003', 'Laboratory Safety Policy (Demo)', 'safety', 'FAC-IT-001', '2026-07-01', '2027-06-30', '1.0', 'active', 'synthetic', 'DOC-POLICIES-001', '{"source_type": "synthetic", "source_document": "DOC-POLICIES-001", "academic_year": "2026-2027", "policy_id": "POLICY-003", "policy_number": "CM-SYN-POL-003", "title": "Laboratory Safety Policy (Demo)", "category": "safety", "applies_to_department_ids": ["DEPT-IT-001"], "applies_to_program_ids": ["PROG-BTECH-IT-001", "PROG-MTECH-IT-001"], "related_course_ids": [], "related_lab_ids": ["LAB-IT-001", "LAB-IT-002", "LAB-IT-003", "LAB-IT-004", "LAB-IT-005", "LAB-IT-006", "LAB-IT-007", "LAB-IT-008", "LAB-IT-009", "LAB-IT-010"], "related_facility_ids": ["FCL-IT-003", "FCL-IT-008"], "owner_faculty_id": "FAC-IT-001", "summary": "Electrical, hardware and data-safety rules for laboratories and maker spaces.", "clauses": ["Food and drinks are not permitted inside any laboratory.", "Hardware in LAB-IT-007 (IoT & Robotics Lab) and FCL-IT-003 (Innovation & Incubation Centre) may be operated only after a safety induction.", "Report damaged cables, overheating equipment or data breaches immediately to the responsible faculty member.", "Emergency exits and fire extinguishers must never be blocked.", "Students must not connect unknown USB devices to the isolated security test network in LAB-IT-005."], "synthetic_notice": "This is a synthetic policy created for CampusMate testing. It is not a Ganpat University regulation.", "effective_from": "2026-07-01", "effective_to": "2027-06-30", "version": "1.0", "status": "active"}');
