INSERT INTO policies (policy_id, policy_number, title, category, owner_faculty_id, effective_from, effective_to, version, status, source_type, source_document, record) VALUES ('POLICY-004', 'CM-SYN-POL-004', 'Capstone Project Submission Policy (Demo)', 'project', 'FAC-IT-020', '2026-07-01', '2027-06-30', '1.0', 'active', 'synthetic', 'DOC-POLICIES-001', '{"source_type": "synthetic", "source_document": "DOC-POLICIES-001", "academic_year": "2026-2027", "policy_id": "POLICY-004", "policy_number": "CM-SYN-POL-004", "title": "Capstone Project Submission Policy (Demo)", "category": "project", "applies_to_department_ids": ["DEPT-IT-001"], "applies_to_program_ids": ["PROG-BTECH-IT-001"], "related_course_ids": ["COURSE-2CEIT504", "COURSE-2CEIT605", "COURSE-2CEIT703"], "related_lab_ids": [], "related_facility_ids": ["FCL-IT-002"], "owner_faculty_id": "FAC-IT-020", "summary": "How B.Tech IT Capstone Project-I, II and III deliverables are submitted.", "clauses": ["Teams of 2–4 students register a project title with the Project Coordinator (FAC-IT-020) by the topic deadline in the academic calendar.", "Each submission must include a report (PDF), source-code repository link, and a 5-minute demo video.", "Final submissions are made through the demo project portal by 17:00 on the deadline date; late submissions lose 10% per day for up to 3 days.", "Similarity above 20% in the report requires a written explanation to the Project Coordinator.", "Printed copies are not required unless requested by the evaluation panel."], "synthetic_notice": "This is a synthetic policy created for CampusMate testing. It is not a Ganpat University regulation.", "effective_from": "2026-07-01", "effective_to": "2027-06-30", "version": "1.0", "status": "active"}');
