INSERT INTO policies (policy_id, policy_number, title, category, owner_faculty_id, effective_from, effective_to, version, status, source_type, source_document, record) VALUES ('POLICY-005', 'CM-SYN-POL-005', 'Project Evaluation Policy (Demo)', 'project', 'FAC-IT-020', '2026-07-01', '2027-06-30', '1.0', 'active', 'synthetic', 'DOC-POLICIES-001', '{"source_type": "synthetic", "source_document": "DOC-POLICIES-001", "academic_year": "2026-2027", "policy_id": "POLICY-005", "policy_number": "CM-SYN-POL-005", "title": "Project Evaluation Policy (Demo)", "category": "project", "applies_to_department_ids": ["DEPT-IT-001"], "applies_to_program_ids": ["PROG-BTECH-IT-001", "PROG-MTECH-IT-001"], "related_course_ids": ["COURSE-2CEIT504", "COURSE-2CEIT605", "COURSE-2CEIT703", "COURSE-3CEIT301", "COURSE-3CEIT401"], "related_lab_ids": [], "related_facility_ids": ["FCL-IT-001", "FCL-IT-002"], "owner_faculty_id": "FAC-IT-020", "summary": "Panel-based evaluation of capstone and major projects.", "clauses": ["Every project is evaluated by a panel of at least two faculty members plus the guide.", "Evaluation happens in two stages: a mid-review and a final presentation in the IT Seminar Hall (FCL-IT-001).", "Demo rubric weights: problem definition 15%, design 20%, implementation 30%, testing 15%, report and presentation 20%.", "Panel scores are finalised within 5 working days and published on the notice board.", "Students may request a re-review within 3 working days of publication."], "synthetic_notice": "This is a synthetic policy created for CampusMate testing. It is not a Ganpat University regulation.", "effective_from": "2026-07-01", "effective_to": "2027-06-30", "version": "1.0", "status": "active"}');
