INSERT INTO policies (policy_id, policy_number, title, category, owner_faculty_id, effective_from, effective_to, version, status, source_type, source_document, record) VALUES ('POLICY-006', 'CM-SYN-POL-006', 'Industrial Training Policy (Demo)', 'project', 'FAC-IT-020', '2026-07-01', '2027-06-30', '1.0', 'active', 'synthetic', 'DOC-POLICIES-001', '{"source_type": "synthetic", "source_document": "DOC-POLICIES-001", "academic_year": "2026-2027", "policy_id": "POLICY-006", "policy_number": "CM-SYN-POL-006", "title": "Industrial Training Policy (Demo)", "category": "project", "applies_to_department_ids": ["DEPT-IT-001"], "applies_to_program_ids": ["PROG-BTECH-IT-001"], "related_course_ids": ["COURSE-2CEIT801"], "related_lab_ids": [], "related_facility_ids": [], "owner_faculty_id": "FAC-IT-020", "summary": "Rules for the Semester VIII INDUSTRIAL TRAINING course (2CEIT801).", "clauses": ["Students must submit an offer letter from the host organisation to the Project Coordinator (FAC-IT-020) before the start of Semester VIII.", "Fortnightly progress reports are due every second Friday.", "A faculty guide is assigned to each student and conducts at least one remote review per month.", "The final training report and presentation are due on the date in the academic calendar (CAL-2026-27-020)."], "synthetic_notice": "This is a synthetic policy created for CampusMate testing. It is not a Ganpat University regulation.", "effective_from": "2026-07-01", "effective_to": "2027-06-30", "version": "1.0", "status": "active"}');
