INSERT INTO notices (notice_id, title, notice_date, department_id, category, effective_date, expiry_date, status, supersedes, source_type, source_document, record) VALUES ('NOTICE-001', 'Orientation programme for new B.Tech IT and M.Tech IT students', '2026-07-01', 'DEPT-IT-001', 'orientation', '2026-07-13', '2026-07-15', 'expired', NULL, 'synthetic', 'DOC-NOTICES-001', '{"source_type": "synthetic", "source_document": "DOC-NOTICES-001", "academic_year": "2026-2027", "notice_id": "NOTICE-001", "title": "Orientation programme for new B.Tech IT and M.Tech IT students", "date": "2026-07-01", "department_id": "DEPT-IT-001", "category": "orientation", "target_audience": ["students_new"], "content": "All newly admitted students of PROG-BTECH-IT-001 (Semester I) and PROG-MTECH-IT-001 (Semester I) must attend the orientation programme from 13 to 15 July 2026 in the IT Seminar Hall (FCL-IT-001, Demo Innovation Block B, Room DB-201). Sessions cover the curriculum, laboratory rules (POLICY-002, POLICY-003) and student services.", "effective_date": "2026-07-13", "expiry_date": "2026-07-15", "related_course_ids": [], "related_faculty_ids": [], "related_lab_ids": [], "related_facility_ids": ["FCL-IT-001"], "related_policy_ids": ["POLICY-002", "POLICY-003"], "related_calendar_ids": ["CAL-2026-27-002"], "supersedes": null, "superseded_by": null, "status": "expired", "version": "1.0"}');
