INSERT INTO notices (notice_id, title, notice_date, department_id, category, effective_date, expiry_date, status, supersedes, source_type, source_document, record) VALUES ('NOTICE-002', 'Odd semester course registration window', '2026-07-02', 'DEPT-IT-001', 'registration', '2026-07-06', '2026-07-10', 'expired', NULL, 'synthetic', 'DOC-NOTICES-001', '{"source_type": "synthetic", "source_document": "DOC-NOTICES-001", "academic_year": "2026-2027", "notice_id": "NOTICE-002", "title": "Odd semester course registration window", "date": "2026-07-02", "department_id": "DEPT-IT-001", "category": "registration", "target_audience": ["students_all"], "content": "Course registration for the odd semester of AY 2026-2027 is open from 6 to 10 July 2026. Semester V students must select one course each from ELECTIVE-I (EGRP-BTECH-IT-05-ELECTIVE-I) and ELECTIVE-II (EGRP-BTECH-IT-05-ELECTIVE-II). Queries: Department Office (FCL-IT-010).", "effective_date": "2026-07-06", "expiry_date": "2026-07-10", "related_course_ids": [], "related_faculty_ids": [], "related_lab_ids": [], "related_facility_ids": ["FCL-IT-010"], "related_policy_ids": [], "related_calendar_ids": ["CAL-2026-27-001"], "supersedes": null, "superseded_by": null, "status": "expired", "version": "1.0"}');
