INSERT INTO faq (faq_id, category, question, answer, department_id, source_type, source_document, record) VALUES ('FAQ-024', 'academics', 'What is the grading scale?', 'Per the official syllabus grade table: 90 and above A+ (10), 80–89 A (9), 70–79 B+ (8), 60–69 B (7), 50–59 C+ (6), 40–49 C (5), below 40 F (0).', 'DEPT-IT-001', 'synthetic', 'DOC-FAQ-001', '{"source_type": "synthetic", "source_document": "DOC-FAQ-001", "academic_year": "2026-2027", "faq_id": "FAQ-024", "category": "academics", "question": "What is the grading scale?", "answer": "Per the official syllabus grade table: 90 and above A+ (10), 80–89 A (9), 70–79 B+ (8), 60–69 B (7), 50–59 C+ (6), 40–49 C (5), below 40 F (0).", "related_entity_ids": ["GRADE-BAND-01", "PROG-BTECH-IT-001"], "department_id": "DEPT-IT-001", "status": "active", "version": "1.0", "answer_basis": "mixed: official curriculum facts cited from the GUNI syllabus; everything else synthetic"}');
