INSERT INTO faq (faq_id, category, question, answer, department_id, source_type, source_document, record) VALUES ('FAQ-025', 'academics', 'How many credits is the B.Tech IT programme?', '174 credits across Semesters I–VIII, computed from the official semester totals (20+20+24+21+23+23+23+20).', 'DEPT-IT-001', 'synthetic', 'DOC-FAQ-001', '{"source_type": "synthetic", "source_document": "DOC-FAQ-001", "academic_year": "2026-2027", "faq_id": "FAQ-025", "category": "academics", "question": "How many credits is the B.Tech IT programme?", "answer": "174 credits across Semesters I–VIII, computed from the official semester totals (20+20+24+21+23+23+23+20).", "related_entity_ids": ["PROG-BTECH-IT-001"], "department_id": "DEPT-IT-001", "status": "active", "version": "1.0", "answer_basis": "mixed: official curriculum facts cited from the GUNI syllabus; everything else synthetic"}');
