INSERT INTO faq (faq_id, category, question, answer, department_id, source_type, source_document, record) VALUES ('FAQ-026', 'academics', 'What is the minimum attendance requirement?', 'The demo Attendance Policy (POLICY-001) expects 75% of lectures and 80% of lab sessions. This is synthetic; the official GUNI documents supplied do not contain an attendance regulation.', 'DEPT-IT-001', 'synthetic', 'DOC-FAQ-001', '{"source_type": "synthetic", "source_document": "DOC-FAQ-001", "academic_year": "2026-2027", "faq_id": "FAQ-026", "category": "academics", "question": "What is the minimum attendance requirement?", "answer": "The demo Attendance Policy (POLICY-001) expects 75% of lectures and 80% of lab sessions. This is synthetic; the official GUNI documents supplied do not contain an attendance regulation.", "related_entity_ids": ["POLICY-001"], "department_id": "DEPT-IT-001", "status": "active", "version": "1.0", "answer_basis": "synthetic"}');
