INSERT INTO faq (faq_id, category, question, answer, department_id, source_type, source_document, record) VALUES ('FAQ-027', 'academics', 'Are there prerequisites for Artificial Intelligence?', 'The official syllabus does not list prerequisites. The synthetic advisory map recommends 2CEIT402 DESIGN AND ANALYSIS OF ALGORITHMS and 2BS3102 DISCRETE MATHEMATICS & PROBABILITY.', 'DEPT-IT-001', 'synthetic', 'DOC-FAQ-001', '{"source_type": "synthetic", "source_document": "DOC-FAQ-001", "academic_year": "2026-2027", "faq_id": "FAQ-027", "category": "academics", "question": "Are there prerequisites for Artificial Intelligence?", "answer": "The official syllabus does not list prerequisites. The synthetic advisory map recommends 2CEIT402 DESIGN AND ANALYSIS OF ALGORITHMS and 2BS3102 DISCRETE MATHEMATICS & PROBABILITY.", "related_entity_ids": ["COURSE-2CEIT602", "COURSE-2CEIT402", "COURSE-2BS3102"], "department_id": "DEPT-IT-001", "status": "active", "version": "1.0", "answer_basis": "synthetic"}');
